<script setup lang="ts">import AppLayout from '@/Layouts/AppLayout.vue'; import { useForm } from '@inertiajs/vue3'; import type { Order } from '@/types'; const props=defineProps<{ order: { data: Order & { progress?: any[] } } }>(); const form=useForm({progress_percentage:25,note:''}); const submit=()=>form.post(route('orders.progress.store', props.order.data.id), { preserveScroll:true });</script><template><AppLayout><div class="grid gap-6 xl:grid-cols-[1fr_380px]"><section class="card"><p class="text-cyan-300">{{ order.data.orderCode }}</p><h1 class="mt-2 text-3xl font-black">{{ order.data.title }}</h1><p class="mt-4 text-slate-300">{{ order.data.description }}</p></section><aside class="card"><h2 class="font-bold">Update progress</h2><form class="mt-4 space-y-3" @submit.prevent="submit"><input v-model="form.progress_percentage" type="range" min="10" max="100" step="5" class="w-full"><div>{{ form.progress_percentage }}%</div><textarea v-model="form.note" class="w-full rounded-2xl bg-white/10" placeholder="Progress note"/><button class="btn-primary">Publish</button></form></aside></div></AppLayout></template>
